package org.apache.commons.lang;

import junit.framework.TestCase;

public class AgentBRT_Lang_44_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        // Test case for a number string with a hexadecimal prefix that might cause issues
        String problematicNumber = "0x1.8p1";
        try {
            Number result = NumberUtils.createNumber(problematicNumber);
            fail("Expected NumberFormatException for a hexadecimal floating-point number");
        } catch (NumberFormatException e) {
            // Expected exception
            assertEquals("0x1.8p1 is not a valid number.", e.getMessage());
        }
    }
}

