package org.apache.commons.lang;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_44_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Test case for a valid number string that should be parsed correctly
        String validNumber = "123.45D";
        try {
            Number result = NumberUtils.createNumber(validNumber);
            assertTrue("Expected a Double instance", result instanceof Double);
            assertEquals("Expected value 123.45", 123.45, result.doubleValue(), 0.0);
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown for a valid number string");
        }
    }
}

